    repeat_frequency                                 TEXT,
    repeat_frequency_gap                             TEXT,
    repeat_frequency_type                            TEXT,
    repeat_frequency_days_of_week                    TEXT,
    repeat_frequency_days_of_month                   TEXT,
    repeat_frequency_month                           TEXT,
    repeat_frequency_ordinal                         TEXT,
    repeat_frequency_ordinal_day                     TEXT,
    location                                         TEXT NOT NULL,
    source_system_key_value                          TEXT,
    source_system_created_date                       DATE,
    source_system_updated_date                       DATE,
    source_system_deleted_date                       DATE,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_scheduled_event PRIMARY KEY (tenant_identifier, scheduled_event_identifier)
);
